<script lang="ts">
	import { onMount } from 'svelte';
	import { defaultContent, normaliseContent, newSection, type ContentPage, type ImageItem, type SiteContent } from '$lib/content/site';
	import { addSiteBase, removeSiteBase, sitePath } from '$lib/utils/site-path';
	import { siteContent } from '$lib/stores/site-content';
	import { supabase, supabaseConfigurationMessage } from '$lib/supabase/client';
	import MediaEditor from '$lib/components/admin/MediaEditor.svelte';
	import ImageField from '$lib/components/admin/ImageField.svelte';
	let draft=$state<SiteContent>(structuredClone(addSiteBase(defaultContent)));
	let activeId=$state('home'); let search=$state(''); let authenticated=$state(false); let localOnly=$state(false); let localAvailable=$state(false); let loading=$state(true); let saving=$state(false); let email=$state(''); let password=$state(''); let status=$state(''); let error=$state(''); let baseline=$state(''); let savedAt=$state(''); let draftAvailable=$state(false); let mediaSearch=$state(''); let newMedia=$state('');
	const active=$derived(draft.pages.find(p=>p.id===activeId));
	const dirty=$derived(Boolean(baseline)&&JSON.stringify(draft)!==baseline);
	const rootLabels:Record<string,string>={home:'Home',about:'About',projects:'Projects','consular-ball':'Consular Ball',contact:'Contact'};
	function pageLabel(p:ContentPage){return rootLabels[p.id]||p.card.title||p.title;}
	const orderedPages=$derived.by(()=>{const result:ContentPage[]=[];const seen=new Set<string>();function visit(id:string){const p=draft.pages.find(p=>p.id===id);if(!p||seen.has(id))return;seen.add(id);result.push(p);const order=p.sections.flatMap(s=>s.tileIds);const children=draft.pages.filter(c=>c.parentId===id&&!rootLabels[c.id]).sort((a,b)=>(order.indexOf(a.id)<0?999:order.indexOf(a.id))-(order.indexOf(b.id)<0?999:order.indexOf(b.id)));children.forEach(c=>visit(c.id));}Object.keys(rootLabels).forEach(visit);draft.pages.forEach(p=>visit(p.id));return result;});
	const filteredPages=$derived(orderedPages.filter(p=>(pageLabel(p)+' '+p.title).toLowerCase().includes(search.toLowerCase())));
	const library=$derived(draft.mediaLibrary.filter(i=>(i.source+' '+i.alt).toLowerCase().includes(mediaSearch.toLowerCase())));
	onMount(async()=>{
		localAvailable=['localhost','127.0.0.1','[::1]'].includes(location.hostname);
		draft=structuredClone($siteContent);baseline=JSON.stringify(draft);draftAvailable=Boolean(localStorage.getItem('pp-draft-v3'));
		try { if(supabase){const {data}=await supabase.auth.getSession();if(data.session){const {data:admin,error:adminError}=await supabase.rpc('is_site_admin');authenticated=Boolean(admin&&!adminError);if(authenticated)await load();}} } finally {loading=false;}
	});
	$effect(()=>{if((!authenticated&&!localOnly)||draftAvailable)return;const snapshot=JSON.stringify(draft);const timeout=window.setTimeout(()=>{try{localStorage.setItem('pp-draft-v3',snapshot);savedAt=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}catch{error='This browser could not save the local draft. Export a backup before leaving.';}},800);return()=>clearTimeout(timeout);});
	async function load(){if(!supabase)return;const {data,error:loadError}=await supabase.from('site_content').select('content').eq('id','primary').maybeSingle();if(loadError){error=loadError.message;return;}if(data?.content){draft=addSiteBase(normaliseContent(data.content));if((data.content.contentVersion||0)<3)status='Piet’s new copy is ready. Publish it when you have finished reviewing.';}baseline=JSON.stringify(draft);}
	async function signIn(event:SubmitEvent){event.preventDefault();error='';if(!supabase){error=supabaseConfigurationMessage;return;}saving=true;try{const {error:loginError}=await supabase.auth.signInWithPassword({email,password});if(loginError)throw loginError;const {data:admin,error:adminError}=await supabase.rpc('is_site_admin');if(adminError||!admin){await supabase.auth.signOut();throw Error('This account has not been added as a website editor.');}authenticated=true;password='';await load();}catch(e){error=e instanceof Error?e.message:'Sign-in failed.';}finally{saving=false;}}
	async function signOut(){if(dirty&&!confirm('Your changes are saved in this browser. Sign out now?'))return;await supabase?.auth.signOut();authenticated=false;localOnly=false;}
	function move<T>(items:T[],index:number,direction:number){const next=index+direction;if(next<0||next>=items.length)return;[items[index],items[next]]=[items[next],items[index]];}
	function paragraphs(value:string){return value.split(/\n\s*\n/).filter(p=>p.trim());}
	function addImage(page:ContentPage,index:number){const item=JSON.parse(JSON.stringify(draft.mediaLibrary[0]||{id:'',src:'',alt:'',caption:'',position:'center'}));item.id=crypto.randomUUID();page.sections[index].images.push(item);}
	function createPage(year=false){const input=prompt(year?'Year of the Consular Ball (four digits)':'Title of the new project');if(!input?.trim())return;if(year&&!/^\d{4}$/.test(input))return;const id=year?`ball-${input}`:input.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!id||draft.pages.some(p=>p.id===id)){error='A page with that name already exists.';return;}const item:ContentPage={id,path:sitePath(year?`/consular-ball/${input}`:`/projects/${id}`),parentId:year?'consular-ball':'projects',title:input,subtitle:'',description:'',kind:year?'year':'story',hidden:false,heroImage:null,card:{title:input,subtitle:'',copy:'',label:year?'':'Explore Project →',image:null},sections:[newSection()]};draft.pages.push(item);draft.pages.find(p=>p.id===item.parentId)?.sections.find(s=>s.layout==='tiles')?.tileIds.push(id);activeId=id;}
	function removePage(item:ContentPage){if(draft.pages.some(p=>p.parentId===item.id)){error='Move this page’s child projects to another category before deleting it.';return;}if(!confirm(`Remove “${item.card.title}” and its tiles? This takes effect after Publish.`))return;draft.pages=draft.pages.filter(p=>p.id!==item.id);for(const p of draft.pages)for(const s of p.sections){s.tileIds=s.tileIds.filter(id=>id!==item.id);if(s.cards)s.cards=s.cards.filter(c=>c.id!==item.id);}activeId='projects';}
	function restoreDraft(){try{const saved=localStorage.getItem('pp-draft-v3');if(saved){draft=addSiteBase(normaliseContent(JSON.parse(saved)));status='Your saved browser draft has been restored.';}draftAvailable=false;}catch{error='The saved draft could not be read.';}}
	function reset(){if(!confirm('Discard the current edits and return to the last published content?'))return;draft=JSON.parse(baseline);status='Edits reset.';}
	function preview(){localStorage.setItem('pp-preview-v3',JSON.stringify(draft));window.open(`${active?.path||sitePath('/')}?preview=1`,'_blank','noopener');}
	function backup(){const blob=new Blob([JSON.stringify(removeSiteBase(draft),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`proud-partners-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);}
	function importBackup(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;void file.text().then(text=>{const data=JSON.parse(text);if(data.contentVersion!==3||!Array.isArray(data.pages))throw Error('Choose a current Proud Partners backup.');if(confirm('Replace this draft with the backup?')){draft=addSiteBase(normaliseContent(data));status='Backup loaded into the draft. Review before publishing.';}}).catch(e=>error=e.message);}
	function validate(){const ids=new Set<string>(),paths=new Set<string>();for(const p of draft.pages){if(!p.title.trim())throw Error('Every page needs a title.');if(ids.has(p.id)||paths.has(p.path))throw Error('Two pages share an address.');ids.add(p.id);paths.add(p.path);}for(const p of draft.pages)for(const s of p.sections){if(s.tileIds.some(id=>!ids.has(id)))throw Error(`A tile on ${p.card.title} points to a missing page.`);} }
	async function publish(){error='';status='';saving=true;try{validate();if(localOnly){localStorage.setItem('pp-draft-v3',JSON.stringify(draft));savedAt=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});status='Local draft saved. Sign in to publish to the shared website.';return;}if(!supabase)throw Error(supabaseConfigurationMessage);const content=removeSiteBase(JSON.parse(JSON.stringify(draft))) as SiteContent;const {error:saveError}=await supabase.from('site_content').upsert({id:'primary',content,updated_at:new Date().toISOString()},{onConflict:'id'});if(saveError)throw saveError;siteContent.set(addSiteBase(content));baseline=JSON.stringify(draft);status='Published. The shared website now has these changes.';}catch(e){error=e instanceof Error?e.message:'Publishing failed.';}finally{saving=false;}}
	function addLibraryImage(){if(!newMedia)return;draft.mediaLibrary.unshift({id:crypto.randomUUID(),src:newMedia,alt:'',caption:'',position:'center',source:'Uploaded image'});newMedia='';siteContent.update(content=>({...content,mediaLibrary:JSON.parse(JSON.stringify(draft.mediaLibrary))}));}
</script>

<svelte:head><title>Website editor — Proud Partners</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<svelte:window onbeforeunload={(event)=>{if(dirty){event.preventDefault();event.returnValue='';}}} />
{#if loading}<div class="login"><p>Opening the editor…</p></div>
{:else if !authenticated&&!localOnly}
	<div class="login"><form onsubmit={signIn}><img src={draft.media.wordmark} alt="Proud Partners" /><h1>Website editor</h1><p>Sign in to edit pages, photos and project tiles.</p><label>Email<input type="email" bind:value={email} autocomplete="username" required /></label><label>Password<input type="password" bind:value={password} autocomplete="current-password" required /></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="primary" type="submit" disabled={saving||!supabase}>{saving?'Signing in…':'Sign in'}</button>{#if !supabase}<p>{supabaseConfigurationMessage}</p>{/if}{#if localAvailable}<button type="button" onclick={()=>{localOnly=true;status='Local editing mode. Preview and export work; shared publishing requires sign-in.';}}>Edit a local draft</button>{/if}<a href={sitePath('/')}>← View website</a></form></div>
{:else}
	<div class="editor">
		<aside><img class="editor-logo" src={draft.media.wordmark} alt="Proud Partners" /><label class="search-label">Find a page<input type="search" bind:value={search} placeholder="Search pages…" /></label><nav aria-label="Pages to edit">{#each filteredPages as item}<button type="button" class:active={activeId===item.id} class:child={Boolean(item.parentId)&&!rootLabels[item.id]} onclick={()=>activeId=item.id}><span>{pageLabel(item)}</span>{#if item.hidden}<small>Hidden</small>{/if}</button>{/each}</nav><div class="sidebar-actions"><button type="button" onclick={()=>createPage()}>+ Project page</button><button type="button" onclick={()=>createPage(true)}>+ Ball year</button><button type="button" class:active={activeId==='settings'} onclick={()=>activeId='settings'}>Navigation & footer</button><button type="button" class:active={activeId==='library'} onclick={()=>activeId='library'}>Photo library</button><button type="button" onclick={signOut}>Sign out</button></div></aside>
		<div class="workspace">
			<header class="toolbar"><div><strong>{active?pageLabel(active):(activeId==='settings'?'Navigation & footer':'Photo library')}</strong><small>{dirty?'Unpublished changes':'No unpublished edits'}{savedAt?` · Draft saved ${savedAt}`:''}</small></div><div class="toolbar-actions"><button type="button" onclick={preview}>Preview</button><button type="button" onclick={backup}>Export backup</button><button class="primary" type="button" onclick={publish} disabled={saving}>{saving?'Publishing…':localOnly?'Save draft':'Publish changes'}</button></div></header>
			<div class="editor-body">
				{#if error}<p class="notice error" role="alert">{error}</p>{/if}{#if status}<p class="notice" role="status">{status}</p>{/if}
				{#if draftAvailable}<div class="notice">A saved browser draft is available. <button type="button" onclick={restoreDraft}>Restore it</button><button type="button" onclick={()=>{if(confirm('Start from the published content and replace the saved browser draft?'))draftAvailable=false;}}>Use published copy</button></div>{/if}
				{#if active}
					<div class="page-heading"><div><p class="kicker">Editing page</p><h1>{pageLabel(active)}</h1><a href={active.path} target="_blank" rel="noreferrer">View current page ↗</a></div><label class="check"><input type="checkbox" bind:checked={active.hidden} disabled={['home','about','projects','contact','consular-ball'].includes(active.id)} /> Hide from tiles</label></div>
					<section class="panel"><h2>Page heading</h2><label>Headline<input bind:value={active.title} /></label><label>Subheading<textarea rows="2" bind:value={active.subtitle}></textarea></label>{#if active.kind==='home'}<MediaEditor label="Main portrait" zoomable bind:image={active.heroImage} />{/if}<details><summary>Page settings</summary><div class="details-body"><label>Search and sharing description<textarea rows="3" bind:value={active.description}></textarea></label><label>Category<select bind:value={active.parentId}><option value="">None</option>{#each draft.pages.filter(p=>p.id!==active.id&&['home','landing','ball'].includes(p.kind)) as parent}<option value={parent.id}>{parent.card.title}</option>{/each}</select></label><p class="hint">Address: {active.path}</p></div></details></section>
					{#if active.kind==='contact'}<section class="panel"><h2>Form wording</h2><p class="hint">The recipient is kept in the private email function and is not displayed on the public page. Edit the title and introduction above.</p>{#each Object.keys(draft.contact.fields) as key}<label>{key}<input bind:value={draft.contact.fields[key as keyof typeof draft.contact.fields]} /></label>{/each}<label>Confirmation message<input bind:value={draft.contact.successMessage} /></label><label>Error message<input bind:value={draft.contact.errorMessage} /></label></section>{/if}
					{#if !['home','about','projects','contact'].includes(active.id)}<details class="panel"><summary>How this page appears in a tile</summary><div class="details-body"><label>Tile title<input bind:value={active.card.title} /></label><label>Tile subheading<input bind:value={active.card.subtitle} /></label><label>Tile description<textarea rows="4" bind:value={active.card.copy}></textarea></label><label>Link text<input bind:value={active.card.label} /></label><MediaEditor label="Tile photo" bind:image={active.card.image} /></div></details>{/if}
					<h2 class="sections-title">Page sections <span>{active.sections.length}</span></h2><p class="hint">Open a section to edit it. Use a blank line between paragraphs. Use **bold**, *italic* or ***bold italic*** for emphasis. Changes stay in your draft until you publish.</p>
					{#each active.sections as section,index (section.id)}
						<details class="panel section-panel"><summary><span class="section-number">{String(index+1).padStart(2,'0')}</span><span>{section.heading||section.paragraphs[0]?.slice(0,65)||({tiles:'Project tiles',gallery:'Photo gallery',video:'Video',stats:'Blue information strip',text:'Text section',split:'Text and image'}[section.layout])}</span><small>{section.layout}</small></summary>
							<div class="details-body"><div class="row tools"><button type="button" disabled={index===0} onclick={()=>move(active.sections,index,-1)}>↑ Move up</button><button type="button" disabled={index===active.sections.length-1} onclick={()=>move(active.sections,index,1)}>↓ Move down</button><button class="danger" type="button" onclick={()=>{if(confirm('Remove this section from the draft?'))active.sections.splice(index,1);}}>Remove section</button></div><label>Section heading<input bind:value={section.heading} /></label><label>Writing<textarea rows={Math.min(20,Math.max(5,section.paragraphs.length*3))} value={section.paragraphs.join('\n\n')} oninput={(event)=>section.paragraphs=paragraphs(event.currentTarget.value)}></textarea></label>
							<div class="row"><label>Layout<select bind:value={section.layout}><option value="text">Writing</option><option value="split">Writing beside a photo</option><option value="gallery">Photo gallery</option><option value="tiles">Clickable tiles</option><option value="video">Video</option><option value="stats">Information strip</option></select></label><label>Background<select bind:value={section.tone}><option value="cream">Cream</option><option value="blue">Dark blue</option></select></label></div>
							{#if section.layout==='stats'}<label>Items (one per line)<textarea rows="5" value={section.stats.join('\n')} oninput={event=>section.stats=event.currentTarget.value.split('\n').filter(Boolean)}></textarea></label>{/if}
							{#if section.layout==='tiles'}<div class="tile-manager"><h3>Tiles, in display order</h3>{#each section.tileIds as id,tileIndex}{@const target=draft.pages.find(p=>p.id===id)}<div class="ordered-item"><span>{target?.card.title||id}</span><button type="button" aria-label={`Move ${target?.card.title} up`} disabled={tileIndex===0} onclick={()=>move(section.tileIds,tileIndex,-1)}>↑</button><button type="button" aria-label={`Move ${target?.card.title} down`} disabled={tileIndex===section.tileIds.length-1} onclick={()=>move(section.tileIds,tileIndex,1)}>↓</button><button type="button" onclick={()=>activeId=id}>Edit page</button><button type="button" onclick={()=>{section.tileIds.splice(tileIndex,1);if(section.cards)section.cards=section.cards.filter(c=>c.id!==id);}}>Remove tile</button></div>{/each}<label>Add an existing page<select value="" onchange={event=>{if(event.currentTarget.value)section.tileIds.push(event.currentTarget.value);event.currentTarget.value='';}}><option value="">Choose a page…</option>{#each draft.pages.filter(p=>p.id!==active.id&&!section.tileIds.includes(p.id)) as p}<option value={p.id}>{p.card.title}</option>{/each}</select></label></div>{/if}
							{#if section.cards?.length}<h3>Copy specific to these featured tiles</h3>{#each section.cards as card}<details><summary>{card.title}</summary><div class="details-body"><label>Title<input bind:value={card.title} /></label><label>Subheading<input bind:value={card.subtitle} /></label><label>Description<textarea rows="4" bind:value={card.copy}></textarea></label><label>Link text<input bind:value={card.label} /></label><MediaEditor label="Featured tile photo" bind:image={card.image} /></div></details>{/each}{/if}
							<h3>Photos</h3>{#each section.images as image,imageIndex (image.id)}<div class="image-edit"><MediaEditor bind:image={section.images[imageIndex]} removable={false} /><div class="row tools"><button type="button" disabled={imageIndex===0} onclick={()=>move(section.images,imageIndex,-1)}>↑ Earlier</button><button type="button" disabled={imageIndex===section.images.length-1} onclick={()=>move(section.images,imageIndex,1)}>↓ Later</button><button type="button" class="danger" onclick={()=>section.images.splice(imageIndex,1)}>Remove</button></div></div>{/each}<button type="button" onclick={()=>addImage(active,index)}>+ Add photo</button>
							<h3>Links</h3>{#each section.links as link,linkIndex}<div class="row"><label>Link text<input bind:value={link.label} /></label><label>Page or website address<input bind:value={link.href} placeholder="/projects or https://…" /></label><button type="button" onclick={()=>section.links.splice(linkIndex,1)}>Remove</button></div>{/each}<button type="button" onclick={()=>section.links.push({label:'',href:''})}>+ Add link</button>
							<h3>Videos</h3>{#each section.videos as video,videoIndex}<label>Video URL<input bind:value={video.url} placeholder="YouTube, Vimeo or an uploaded video URL" /></label><label>Caption<input bind:value={video.caption} /></label><button type="button" onclick={()=>section.videos.splice(videoIndex,1)}>Remove video</button>{/each}<button type="button" onclick={()=>section.videos.push({url:'',caption:'',poster:''})}>+ Add video</button>
						</div></details>
					{/each}
					<div class="row page-bottom"><button type="button" onclick={()=>active.sections.push(newSection())}>+ Add section</button><button type="button" onclick={reset}>Discard unpublished edits</button>{#if !['home','about','projects','contact','consular-ball'].includes(active.id)}<button class="danger" type="button" onclick={()=>removePage(active)}>Delete page</button>{/if}</div>
				{:else if activeId==='settings'}
					<section class="panel"><h1>Navigation & footer</h1><label>Organisation name<input bind:value={draft.site.name} /></label><label>Footer description<textarea rows="4" bind:value={draft.site.description}></textarea></label><label>Location<input bind:value={draft.site.location} /></label><label>Footer tagline<input bind:value={draft.site.footerTagline} /></label><ImageField label="Main logo" bind:value={draft.media.wordmark} /><ImageField label="Round mark" bind:value={draft.media.mark} /><h2>Menu links</h2>{#each draft.site.navigation as item,i}<div class="row"><label>Label<input bind:value={item.label} /></label><label>Address<input bind:value={item.href} /></label><button type="button" onclick={()=>move(draft.site.navigation,i,-1)}>↑</button><button type="button" onclick={()=>move(draft.site.navigation,i,1)}>↓</button><button type="button" onclick={()=>draft.site.navigation.splice(i,1)}>Remove</button></div>{/each}<button type="button" onclick={()=>draft.site.navigation.push({label:'',href:''})}>+ Menu link</button><hr /><label>Restore from a backup<input type="file" accept="application/json" onchange={importBackup} /></label></section>
				{:else if activeId==='library'}
					<section class="panel"><h1>Photo library</h1><p class="hint">Piet’s image choices are grouped by their original folder names. Selecting another image does not change the source file.</p><input type="search" bind:value={mediaSearch} placeholder="Search by project, folder or filename…" /><ImageField label="Upload a new library photo" bind:value={newMedia} /><button type="button" disabled={!newMedia} onclick={addLibraryImage}>Add to library</button><div class="library-grid">{#each library as image}<figure><img src={image.src} alt={image.alt} loading="lazy" /><figcaption>{image.source||image.alt}</figcaption></figure>{/each}</div></section>
				{/if}
			</div>
		</div>
	</div>
{/if}

<style>
	:global(.admin-shell) { background:var(--cream); font-family:var(--font-rounded); font-size:.94rem; }
	button { padding:.65rem .9rem; border:1px solid var(--line); border-radius:.55rem; background:var(--cream); color:var(--navy); cursor:pointer; font-family:var(--font-rounded); font-size:.8rem; }
	button:hover { border-color:var(--blue); background:var(--cream-deep); } button:disabled { opacity:.45; cursor:default; } button.primary { background:var(--navy); border-color:var(--navy); color:var(--cream); } button.danger { color:#983d3d; }
	label { display:grid; gap:.4rem; margin-bottom:.9rem; font-size:.83rem; color:var(--ink-soft); } input,textarea,select { width:100%; min-width:0; padding:.75rem .85rem; border:1px solid var(--line); border-radius:.5rem; color:var(--ink); background:var(--cream); font:inherit; line-height:1.65; } textarea { resize:vertical; } input[type=checkbox] { width:auto; accent-color:var(--blue); }
	h1 { margin:0 0 1rem; font-family:var(--font-rounded); font-size:1.8rem; line-height:1.3; } h2 { font-family:var(--font-rounded); font-size:1.15rem; margin:0 0 1.25rem; } h3 { margin:1.4rem 0 .8rem; font-size:.95rem; }
	.login { min-height:100vh; display:grid; place-items:center; padding:2rem 1rem; } .login form { width:min(100%,26rem); display:grid; gap:1rem; } .login img { width:15rem; margin-bottom:1rem; } .login p,.login a { font-size:.9rem; margin:0; }
	.editor { display:grid; grid-template-columns:16rem minmax(0,1fr); min-height:100vh; } aside { position:sticky; top:0; height:100svh; padding:1.5rem 1rem; overflow-y:auto; background:var(--cream-deep); border-right:1px solid var(--line); } .editor-logo { display:block; width:12rem; margin:0 0 2rem; }
	.search-label { margin:0 0 1rem; } aside nav { display:grid; gap:.15rem; } aside nav button { text-align:left; display:flex; justify-content:space-between; gap:.5rem; padding:.65rem .75rem; border:0; background:transparent; line-height:1.45; font-size:.78rem; } aside nav button.child { padding-left:1.15rem; } aside button.active { background:var(--navy); color:var(--cream); } .sidebar-actions { display:grid; gap:.5rem; margin-top:1.5rem; padding-top:1rem; border-top:1px solid var(--line); }
	.workspace { min-width:0; } .toolbar { position:sticky; top:0; z-index:5; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:1rem; padding:1rem 2rem; background:var(--cream); border-bottom:1px solid var(--line); } .toolbar strong { font-size:.95rem; } .toolbar small { display:block; color:var(--ink-soft); font-size:.72rem; margin-top:.25rem; } .toolbar-actions { display:flex; gap:.5rem; }
	.editor-body { max-width:65rem; margin:auto; padding:2rem; } .panel { padding:1.5rem; border:1px solid var(--line); border-radius:.85rem; background:color-mix(in srgb,var(--cream-deep) 35%,var(--cream)); margin-bottom:1.25rem; } .page-heading { display:flex; justify-content:space-between; gap:1rem; align-items:start; margin:1rem 0 2rem; } .page-heading a { font-size:.8rem; color:var(--blue); } .kicker { margin:0 0 .5rem; text-transform:uppercase; letter-spacing:.12em; font-size:.7rem; color:var(--blue); } .check { display:flex; align-items:center; gap:.5rem; flex-shrink:0; }
